#!/usr/bin/env python3
"""Deterministic multi-profile PDFs generated by independent ReportLab.

CI-only; no Shiva dependency, no user files, and no network calls at runtime.
A pinned ReportLab wheel supplies the writer, rather than the Rust lopdf parser
or the pdf-lib generator used by the preceding CC0 external corpus.
"""
import argparse
import hashlib
from pathlib import Path

from reportlab import Version as REPORTLAB_VERSION
from reportlab.lib.pagesizes import A4, landscape, letter
from reportlab.pdfgen import canvas

# Fingerprints independently observed to agree on Linux and Windows CI.
# Any dependency, OS or generator output drift fails before Rust reads PDFs.
PROFILES = (
    ("reportlab-1-page.pdf", 1, False,
     "f7aa5fdd269eba8389cda766e7679e381157cf3bde50dbb3d9b425c3ac6d0ef3"),
    ("reportlab-12-pages.pdf", 12, True,
     "0cccac77ff83c65b86e7a1e02ed668b383180178929c6ef993d2b445d670b8c5"),
    ("reportlab-rotated-3-pages.pdf", 3, True,
     "6a935e0e8c4d72e0604d4d22c6585fdc8a4fe78d2eda7d6bc1a5ec59b654ba9e"),
)
MAX_PDF_SIZE = 2 * 1024 * 1024


def create_pdf(path: Path, count: int, complex_layout: bool) -> None:
    pdf = canvas.Canvas(
        str(path),
        pagesize=A4,
        pageCompression=1 if complex_layout else 0,
        invariant=1,
    )
    pdf.setTitle("Shiva independent ReportLab PDF QA")
    pdf.setAuthor("Shiva deterministic QA only")
    pdf.setSubject("No user content")
    for page in range(1, count + 1):
        # Different MediaBoxes and rotation profiles, including PDF /Rotate.
        size = landscape(letter) if complex_layout and page % 2 == 0 else A4
        pdf.setPageSize(size)
        # Keep ordinary multi-page text within the visible page boundary.
        # Rotations receive their own purpose-built 3-page fixture.
        rotation = (0, 90, 180)[(page - 1) % 3] if count == 3 else 0
        pdf.setPageRotation(rotation)
        _, height = size
        marker = f"RLQA-{page:03}-OF-{count:03}"
        pdf.setFont("Helvetica-Bold", 14)
        pdf.drawString(45, height - 60, marker)
        pdf.setFont("Courier", 9)
        pdf.drawString(45, height - 78, f"INDEPENDENT-PRODUCER REPORTLAB PROFILE {count}")
        pdf.setFont("Times-Roman", 10)
        for n in range(3):
            pdf.drawString(45, height - 106 - n * 20, f"Body-{n}: alpha beta 123 / [] ()")
        pdf.showPage()
    pdf.save()


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", required=True, type=Path)
    args = parser.parse_args()
    if REPORTLAB_VERSION != "4.4.10":
        raise RuntimeError("unapproved ReportLab generator version")
    # Prevent writing over existing QA files or following a pre-existing tree.
    args.out.mkdir(mode=0o700, parents=True, exist_ok=False)
    for filename, pages, layout, expected_sha256 in PROFILES:
        path = args.out / filename
        create_pdf(path, pages, layout)
        raw = path.read_bytes()
        if not 100 <= len(raw) <= MAX_PDF_SIZE or not raw.startswith(b"%PDF-"):
            raise ValueError("ReportLab output failed size/PDF header bounds")
        sha = hashlib.sha256(raw).hexdigest()
        if sha != expected_sha256:
            raise ValueError("generated PDF SHA-256 changed from cross-platform pinned corpus")
        print(f"SHIVA_RL_GENERATED={filename};bytes={len(raw)};sha256={sha};pages={pages}")
    print(f"SHIVA_RL_GENERATOR=pass;version={REPORTLAB_VERSION};profiles={len(PROFILES)}")


if __name__ == "__main__":
    main()
